        tokenManager.jjmatchedKind = 27; // "or" token
        tokenManager.input_stream = stream;

        // Call the method under test
        Token result = tokenManager.jjFillToken();

        // Verify results
        assertEquals(27, result.kind);
        assertEquals("or", result.image);
